// MARK: - Draft

/// One learner draft for one exercise, kept on this device only.
/// There is no server table for studio drafts, and drafts are
/// never mirrored anywhere. See StudioDraftStore.
struct StudioDraft: Identifiable, Codable, Hashable {
    let id: UUID
    let exerciseID: String
    var text: String
    /// Titles of the required sections the learner ticked off.
    var completedSections: [String]
    let createdAt: Date
    var updatedAt: Date
    /// When the learner last asked for an AI review of this
    /// draft, if ever. Kept for stored drafts and tests; no UI
    /// in the app presents it.
    var aiReviewRequestedAt: Date?

    init(
        id: UUID = UUID(),
        exerciseID: String,
        text: String,
        completedSections: [String] = [],
        createdAt: Date = Date(),
        updatedAt: Date = Date(),
        aiReviewRequestedAt: Date? = nil
    ) {
        self.id = id
        self.exerciseID = exerciseID
        self.text = text
        self.completedSections = completedSections
        self.createdAt = createdAt
        self.updatedAt = updatedAt
        self.aiReviewRequestedAt = aiReviewRequestedAt
    }

    var wordCount: Int {
        StudioRubricReview.wordCount(text)
    }

    var hasRequestedAIReview: Bool {
        aiReviewRequestedAt != nil
    }
}

// MARK: - Local rubric review

/// One deterministic check on a draft. The review is a checklist,
/// not AI: it looks only for section keywords, word counts, list
/// lines and Gherkin keywords. It never judges quality, and it
/// never presents its result as an assessment of the writing.
struct StudioRubricCheck: Identifiable, Hashable {
    let id: String
    let label: String
    let passed: Bool
    let detail: String
}

/// The deterministic local review. Pure functions with no
/// network, no AI and no stored state, so the same draft always
/// gets the same result.
enum StudioRubricReview {
    /// Words in a draft: runs of non-whitespace characters.
    static func wordCount(_ text: String) -> Int {
        text.split(whereSeparator: { $0.isWhitespace }).count
    }

    /// List lines in a draft: non-empty lines starting with a
    /// bullet (-, *, or bullet character), a number followed by
    /// "." or ")", or "AC" followed by a number, a space or a
    /// colon. The counting rule is stated in the check detail,
    /// so the number is never mistaken for a quality judgement.
    static func criteriaLineCount(_ text: String) -> Int {
        text.components(separatedBy: .newlines).filter { line in
            let trimmed = line.trimmingCharacters(in: .whitespaces)
            guard !trimmed.isEmpty else { return false }
            if trimmed.hasPrefix("-") || trimmed.hasPrefix("*") || trimmed.hasPrefix("•") {
                return true
            }
            if let first = trimmed.first, first.isNumber {
                let rest = trimmed.drop(while: { $0.isNumber })
                if rest.hasPrefix(".") || rest.hasPrefix(")") { return true }
            }
            let upper = trimmed.uppercased()
            if upper.hasPrefix("AC") {
                let rest = upper.dropFirst(2)
                if let first = rest.first, first.isNumber || first == " " || first == ":" || first == "-" {
                    return true
                }
            }
            return false
        }.count
    }

    /// True when a whole word appears in the text, case-insensitively.
    /// Splitting on non-alphanumeric characters keeps "Given" from
    /// matching inside another word.
    static func containsWord(_ word: String, in text: String) -> Bool {
        let needle = word.lowercased()
        return text.lowercased().split(whereSeparator: { !$0.isLetter && !$0.isNumber }).contains { String($0) == needle }
    }

    /// All checks for one exercise and draft, in display order:
    /// word count, one check per required section, then the
    /// criteria-count and Gherkin checks when the exercise has
    /// them. An empty draft returns the word-count check only,
    /// marked as not passed, so the review never pretends an
    /// empty draft was reviewed section by section.
    static func checks(for exercise: StudioExercise, draft: String) -> [StudioRubricCheck] {
        let trimmed = draft.trimmingCharacters(in: .whitespacesAndNewlines)
        let words = wordCount(trimmed)
        var result: [StudioRubricCheck] = []
        let wordDetail: String
        if words == 0 {
            wordDetail = "No words yet. \(exercise.wordCountGuidance)"
        } else if words < exercise.suggestedMinimumWords {
            wordDetail = "\(words) words. \(exercise.wordCountGuidance)"
        } else if words > exercise.suggestedMaximumWords {
            wordDetail = "\(words) words, above the suggested maximum. \(exercise.wordCountGuidance) Consider tightening the draft."
        } else {
            wordDetail = "\(words) words. \(exercise.wordCountGuidance)"
        }
        result.append(StudioRubricCheck(
            id: "words",
            label: "Word count",
            passed: words >= exercise.suggestedMinimumWords,
            detail: wordDetail
        ))
        guard words > 0 else { return result }
        let lowerDraft = trimmed.lowercased()
        for section in exercise.requiredSections {
            let found = section.keywords.first(where: { lowerDraft.contains($0.lowercased()) })
            result.append(StudioRubricCheck(
                id: "section-\(section.title)",
                label: "Section: \(section.title)",
                passed: found != nil,
                detail: found != nil
                    ? "Found a mention of \"\(found!)\". This only checks that the section is mentioned, not that it is complete."
                    : "Not found yet. Add a section covering: \(section.title)."
            ))
        }
        if let minimum = exercise.minimumAcceptanceCriteria {
            let count = criteriaLineCount(trimmed)
            result.append(StudioRubricCheck(
                id: "criteria",
                label: "Acceptance criteria count",
                passed: count >= minimum,
                detail: "Counted \(count) list lines (lines starting with a bullet, a number, or AC). At least \(minimum) expected. This counts lines only; it does not judge whether each criterion is testable."
            ))
        }
        if exercise.requiresGherkin {
            for keyword in ["Given", "When", "Then"] {
                let found = containsWord(keyword, in: trimmed)
                result.append(StudioRubricCheck(
                    id: "gherkin-\(keyword)",
                    label: "Gherkin keyword: \(keyword)",
                    passed: found,
                    detail: found
                        ? "Found \"\(keyword)\"."
                        : "Not found yet. Each scenario needs Given, When and Then."
                ))
            }
        }
        return result
    }
}

// MARK: - BABOK-based teaching content (Studio rebuild, 13 Nov 2026)

// Teaching lessons for the BA and PO Studio. Every lesson introduces
// and explains one BABOK item, then teaches how to write its output,
// with one worked example. Content is authored as logical paragraphs:
// every text field that renders as prose is an array of paragraph
// strings, one idea per paragraph. A later pass owns shared paragraph
// rendering; the Studio views render these arrays with breathing room
// using existing design tokens.
//
// COPYRIGHT: this content works from BABOK task, technique,
// competency and perspective NAMES and structure only. No BABOK Guide
// text was used. All prose is original Payments Training Hub authorship,
// including the staged BA section material, which was written
// originally for Payments Training Hub. The Studio shows the
// no-IIBA-endorsement disclaimer in StudioDisclaimer.
// No em dashes in any user-facing text.

/// The no-IIBA-endorsement disclaimer, shown on the Studio home and
/// in every lesson detail view.
enum StudioDisclaimer {
    static let text = "This Studio teaches business analysis using the structure and names of the BABOK Guide v3 knowledge areas, tasks, techniques, competencies, and perspectives. All explanations, examples, and practice material are original Payments Training Hub authorship. This material is not affiliated with, sponsored, or endorsed by IIBA. BABOK is a registered trademark of the International Institute of Business Analysis."
}

/// The three Studio levels, in learning order. Every lesson carries
/// one level, and the Studio presents Level 1, then Level 2, then
/// Level 3, in that order.
enum StudioLevel: Int, CaseIterable, Identifiable, Hashable {
    case foundation = 1
    case practitioner = 2
    case advanced = 3

    var id: Int { rawValue }

    var displayName: String {
        switch self {
        case .foundation: return "Level 1: Foundations"
        case .practitioner: return "Level 2: Practitioner"
        case .advanced: return "Level 3: Advanced"
        }
    }

    var shortName: String {
        switch self {
        case .foundation: return "Level 1"
        case .practitioner: return "Level 2"
        case .advanced: return "Level 3"
        }
    }

    var blurb: String {
        switch self {
        case .foundation: return "Start here. The key concepts behind all analysis, then planning and elicitation, the core techniques for gathering and recording information, working with people, and the agile way of working."
        case .practitioner: return "The working craft. Managing requirements through their life, specifying and modelling them, the modelling and decision techniques, and the technology and process perspectives."
        case .advanced: return "Judgement and strategy. Strategy analysis, solution evaluation, the analytical and commercial techniques, professional judgement, and the enterprise perspectives."
        }
    }

    var systemImage: String {
        switch self {
        case .foundation: return "1.circle"
        case .practitioner: return "2.circle"
        case .advanced: return "3.circle"
        }
    }
}

/// What kind of BABOK item a lesson teaches. Concepts are the
/// Chapter 2 key concepts, taught first in Level 1, before the
/// tasks that build on them.
enum StudioLessonKind: String, CaseIterable, Hashable {
    case concept
    case task
    case technique
    case competency
    case perspective
    case orientation

    var displayName: String {
        switch self {
        case .concept: return "Concept"
        case .task: return "Task"
        case .technique: return "Technique"
        case .competency: return "Competency"
        case .perspective: return "Perspective"
        case .orientation: return "Orientation"
        }
    }

    var systemImage: String {
        switch self {
        case .concept: return "lightbulb"
        case .task: return "checklist"
        case .technique: return "wrench.and.screwdriver"
        case .competency: return "person.crop.circle.badge.checkmark"
        case .perspective: return "eye"
        case .orientation: return "map"
        }
    }

    /// Display order within a level: concepts, then tasks, then
    /// techniques, then competencies, then perspectives, then
    /// orientation lessons.
    var sortOrder: Int {
        switch self {
        case .concept: return 0
        case .task: return 1
        case .technique: return 2
        case .competency: return 3
        case .perspective: return 4
        case .orientation: return 5
        }
    }
}

/// The six BABOK knowledge areas, in BABOK order.
enum StudioKnowledgeArea: String, CaseIterable, Hashable {
    case planning
    case elicitation
    case lifecycle
    case strategy
    case analysisDesign
    case solutionEvaluation

    var displayName: String {
        switch self {
        case .planning: return "Business Analysis Planning and Monitoring"
        case .elicitation: return "Elicitation and Collaboration"
        case .lifecycle: return "Requirements Life Cycle Management"
        case .strategy: return "Strategy Analysis"
        case .analysisDesign: return "Requirements Analysis and Design Definition"
        case .solutionEvaluation: return "Solution Evaluation"
        }
    }

    /// Introduction paragraphs: the staged section description,
    /// plus one original paragraph on why the area matters.
    var introduction: [String] {
        switch self {
        case .planning: return ["This section teaches how to plan business analysis work, engage stakeholders, govern decisions, manage analysis information, and improve how analysis is performed over time.", "Planning is the work that makes the rest of the analysis possible. It is revisited whenever scope, risk, or timing changes, because a plan written once and never revised is a record of what was believed at the start, not a guide to the work ahead."]
        case .elicitation: return ["This section teaches how to prepare for, run, and confirm elicitation, and how to share business analysis information and work well with stakeholders.", "Elicitation is the drawing out of information from stakeholders and other sources, and collaboration is the work that keeps stakeholders engaged while it happens. The two belong together: information gathered without collaboration is rarely trusted, and collaboration without information is only conversation."]
        case .lifecycle: return ["This section teaches how to trace, maintain, prioritize, change and approve requirements across their life, so the delivered work stays linked to real business needs.", "Requirements live longer than the meetings that created them. This area keeps them accurate, ordered, and linked, from the first draft to the last change, so the delivered work stays connected to the needs it serves."]
        case .strategy: return ["This section teaches how a business analyst understands the present position, shapes a realistic future position, weighs risks, and chooses a practical way to get from one to the other.", "Strategy analysis looks before it leaps. It builds an honest picture of the present, shapes a realistic picture of the future, weighs the risks, and chooses a practical route between the two, before any solution is designed in detail."]
        case .analysisDesign: return ["This section teaches how to specify and model requirements, check them, confirm they meet the need, structure them, compare design options, and recommend the solution with the strongest value.", "This area turns needs into requirements that a delivery team can build and test, checks those requirements, confirms they serve the need, organises them, and compares the design options that could meet them. It is where analysis becomes specific enough to build from."]
        case .solutionEvaluation: return ["This section teaches how to check whether a live solution delivers value, find its limits, and recommend the next best action.", "A solution that is live is not necessarily a solution that delivers value. This area checks whether the value arrived, finds the limits of the solution and of the organisation around it, and recommends the next best action on evidence."]
        }
    }
}

/// One section of the output a lesson teaches the learner to write:
/// its title and one paragraph of guidance on what goes in it.
struct StudioOutputSection: Hashable {
    let title: String
    let guidance: String
}

/// One supporting practice scenario, adapted from the staged BA
/// section material. Scenarios are PRACTICE: the detail view shows
/// them only after the teaching, under a Practice heading, never
/// mixed into the explanation.
struct StudioPracticeScenario: Identifiable, Hashable {
    let id: String
    let title: String
    let takeaway: String
    /// The scenario story, as logical paragraphs.
    let story: [String]
}

/// One supporting practice question, adapted from the staged BA
/// section interview questions. The answer is a model answer in
/// paragraph form, shown only in the Practice section, after the
/// learner has had the chance to answer for themselves.
struct StudioPracticeQuestion: Identifiable, Hashable {
    let id: String
    let question: String
    /// The model answer, as logical paragraphs. Empty when the
    /// question is a reflection prompt with no model answer.
    let answer: [String]
}

/// One teaching lesson: what a BABOK item is and why it matters,
/// how to write its output, and one worked example. Every prose
/// field is an array of paragraph strings, one idea per paragraph.
/// Practice material (scenarios, questions, linked exercises, and
/// the write-your-own workspace) is kept in separate fields and is
/// rendered after the teaching, under a Practice heading.
struct StudioLesson: Identifiable, Hashable {
    let id: String
    let title: String
    let subtitle: String
    let kind: StudioLessonKind
    let level: StudioLevel
    let knowledgeArea: StudioKnowledgeArea?
    /// The BABOK chapter reference for the item name, for example
    /// "10.25" for Interviews. Names and structure only; no
    /// BABOK text is reproduced. Nil for orientation lessons,
    /// which teach how to choose and combine techniques.
    let babokReference: String?
    /// What the item is and why it matters, as paragraphs.
    let explanation: [String]
    /// The name of the output this lesson teaches the learner
    /// to write, for example a stakeholder engagement plan.
    let outputName: String
    /// The structure of the output: its sections, in order,
    /// each with guidance on what goes in it.
    let outputStructure: [StudioOutputSection]
    /// How to write the output, as paragraphs.
    let howToWrite: [String]
    let workedExampleTitle: String
    /// One realistic worked example, as paragraphs. Fictional
    /// illustration, labelled as an example in the UI.
    let workedExample: [String]
    let keyPoints: [String]
    let practiceScenarios: [StudioPracticeScenario]
    let practiceQuestions: [StudioPracticeQuestion]
    /// Existing practice exercises that follow this teaching.
    let linkedExerciseIDs: [String]
    let suggestedMinimumWords: Int
    let suggestedMaximumWords: Int

    var wordCountGuidance: String {
        "Suggested \(suggestedMinimumWords) to \(suggestedMaximumWords) words."
    }

    var hasPractice: Bool {
        !practiceScenarios.isEmpty || !practiceQuestions.isEmpty || !linkedExerciseIDs.isEmpty
    }

    /// The review prompt for a write-your-own draft. Kept for
    /// stored drafts and tests; no UI in the app presents it.
    func aiReviewPrompt(draft: String) -> String {
        "Please review my draft for the lesson \"\(title)\" (\(kind.displayName), \(level.displayName)). I was learning how to write: \(outputName).\n\nMy draft:\n\(draft)\n\nPlease review my draft against what the lesson taught. Point out what is missing or unclear, and suggest improvements. Do not rewrite the draft for me."
    }
}

extension StudioLesson {
    /// All 34 Chapter 2 key concepts, in chapter order: the BACCM
    /// overview and its six core concepts (2.1), the eight key
    /// terms (2.2), the requirements classification schema and its
    /// five requirement kinds (2.3), the stakeholders overview and
    /// its eleven roles (2.4), and requirements and designs (2.5).
    /// All are Level 1: the foundations every later lesson builds
    /// on. Names and structure only; all prose is original
    /// Payments Training Hub authorship.
    static let keyConcepts: [StudioLesson] = [
    StudioLesson(
        id: "lesson-concept-baccm",
        title: "The Business Analysis Core Concept Model (BACCM)",
        subtitle: "Six ideas that sit behind every business analysis task, and how they fit together.",
        kind: .concept,
        level: .foundation,
        knowledgeArea: nil,
        babokReference: "2.1",
        explanation: [
            "The Business Analysis Core Concept Model, known as the BACCM, is a simple frame for thinking about business analysis work. It names six ideas that sit behind every task in this Studio: Change, Need, Solution, Stakeholder, Value, and Context. Whatever the task, the analyst can ask six questions: what is changing, what need drives it, what solution answers it, who is affected, what value it delivers, and what circumstances surround it.",
            "The six ideas depend on each other. A need gives rise to a change, and a change creates a solution, but a change can also reveal a new need. Value is judged by stakeholders, and only inside a context: the same solution can be valuable in one setting and harmful in another. When one idea is unclear, the others wobble too. An unclear need, for example, makes it impossible to judge whether a solution delivers value.",
            "Use the model as a check, not as a form to fill in. Before starting a piece of analysis, run through the six ideas and note which ones are clear and which are still open. If the need is vague, clarify it before designing. If the stakeholders are unnamed, find them before deciding. The six lessons that follow take each idea in turn and teach how to write it down well."
        ],
        outputName: "BACCM check note",
        outputStructure: [
            StudioOutputSection(title: "Change", guidance: "What is changing, in one sentence, and what triggered it."),
            StudioOutputSection(title: "Need", guidance: "The problem or opportunity, stated without naming a solution."),
            StudioOutputSection(title: "Solution", guidance: "The proposed way of meeting the need, and what it changes."),
            StudioOutputSection(title: "Stakeholder", guidance: "Who is affected, and what each group wants from the change."),
            StudioOutputSection(title: "Value", guidance: "What value the change delivers, and to whom, in this context."),
            StudioOutputSection(title: "Context", guidance: "The circumstances that shape the change: rules, systems, timing, and habits.")
        ],
        howToWrite: [
            "Write one short entry per idea, in plain words, and mark each entry as clear or open. Keep the need free of solution language: a need that already names the answer has skipped the analysis. End by naming the most open idea and the next step that will clarify it, with an owner and a date. Revisit the note when facts change, because a check written once and never revised soon describes a change that no longer exists.",
            "Run the check at the start of a piece of work, and again whenever a major fact changes. The check is quick: six short entries, honestly marked. Its value is not the note itself, but the gaps it reveals before they become expensive."
        ],
        workedExampleTitle: "Worked example: BACCM check for a payment status change",
        workedExample: [
            "Change: the operations screen will show live payment status. Need: officers cannot answer customer queries without manual checks, which are slow and sometimes wrong. Solution: show the latest status and its time on the screen officers already use. Stakeholders: operations officers, the corporate banking team, compliance, and the technology team. Value: faster, accurate answers for customers, and less manual checking for officers. Context: status reports arrive from three systems, and one payment type has no status report at all.",
            "The check showed two open ideas. The need was clear, but the context held a gap: the payment type with no status report would still need manual checks, and the value claim had to be narrowed to the payment types the change actually covers. The analyst recorded that limit in the note and agreed a separate investigation for the missing report, so the change was judged honestly."
        ],
        keyPoints: [
            "The six ideas are Change, Need, Solution, Stakeholder, Value, and Context.",
            "Each idea depends on the others; an unclear need makes value impossible to judge.",
            "Use the model as a check at the start of a piece of work, and revisit it as facts change."
        ],
        practiceScenarios: [],
        practiceQuestions: [],
        linkedExerciseIDs: [],
        suggestedMinimumWords: 120,
        suggestedMaximumWords: 350
    ),
    StudioLesson(
        id: "lesson-concept-change",
        title: "Change",
        subtitle: "Change is the act of transformation in response to a need.",
        kind: .concept,
        level: .foundation,
        knowledgeArea: nil,
        babokReference: "2.1",
        explanation: [
            "Change is the act of transformation in response to a need. Something moves from how it is now to how it should be: a process is redesigned, a system is replaced, a rule is rewritten, or a team starts working in a new way. Change is deliberate and controlled: it is planned, agreed, and checked, rather than left to drift. In business analysis, every task serves a change, even when the change is small.",
            "Change always has a before and an after, and the analyst must understand both. The current state shows what happens today, including the workarounds people rely on. The future state shows what should happen after the change, in enough detail to build and test. Change also has a cost: time, effort, learning, and risk. A change statement that describes only the after picture hides the journey, and the journey is where most changes fail."
        ],
        outputName: "Change statement",
        outputStructure: [
            StudioOutputSection(title: "Current state", guidance: "How the work happens today, including workarounds and pain points."),
            StudioOutputSection(title: "Future state", guidance: "How the work should happen after the change, in enough detail to build from."),
            StudioOutputSection(title: "Trigger", guidance: "The need or event that makes this change necessary now."),
            StudioOutputSection(title: "Scope", guidance: "What the change covers, and what it deliberately leaves out.")
        ],
        howToWrite: [
            "Describe the current state from evidence, not from the official process alone: watch the work, read the logs, and ask the people who do it daily. Then describe the future state at the same level of detail, so the gap between the two is visible. State the trigger plainly, and draw the scope boundary in words: what is in, what is out, and why. A change statement that cannot say what is out of scope is not finished."
        ],
        workedExampleTitle: "Worked example: change statement for a payment status screen",
        workedExample: [
            "Current state: officers answer payment status queries by telephoning the back office, because the screen shows no status for one payment type. Future state: officers read the status and its time from the screen, for every payment type, and telephone only when the screen says no status has been received. Trigger: customer complaints about slow and inconsistent answers. Scope: the screen and the status feed; the underlying payment systems are out of scope.",
            "Writing the two states side by side exposed a gap the team had missed: the future state assumed a status report that one payment type does not produce. The scope was narrowed to the payment types with a report, and a separate change was raised for the missing report. The change statement recorded both decisions, so no one later assumed the narrow change covered everything."
        ],
        keyPoints: [
            "Change moves work from a current state to a future state, deliberately and under control.",
            "Describe both states from evidence, at the same level of detail.",
            "State the scope boundary, including what is deliberately left out."
        ],
        practiceScenarios: [],
        practiceQuestions: [],
        linkedExerciseIDs: [],
        suggestedMinimumWords: 120,
        suggestedMaximumWords: 350
    ),
    StudioLesson(
        id: "lesson-concept-need",
        title: "Need",
        subtitle: "A need is a problem to solve or an opportunity to seize.",
        kind: .concept,
        level: .foundation,
        knowledgeArea: nil,
        babokReference: "2.1",
        explanation: [
            "A need is a problem to solve or an opportunity to seize. Problems show up as pain: errors, delays, cost, risk, or unhappy customers. Opportunities show up as possibility: a new market, a faster service, or a capability competitors already offer. Needs motivate stakeholders to act, and acting creates change. Change can also create new needs: a new system may reveal a training need, or a new process may expose a control gap.",
            "A good need statement stays free of solutions. It describes the pain or the possibility, who feels it, and what it costs, without naming the answer. The moment a need statement says what should be built, analysis has been skipped and the organisation is committed to an answer nobody tested. Needs also need evidence: volumes, timings, examples, and the words of the people affected. A need stated without evidence is an opinion, and opinions are a weak basis for spending money."
        ],
        outputName: "Need statement",
        outputStructure: [
            StudioOutputSection(title: "Problem or opportunity", guidance: "What hurts, or what is possible, in plain words."),
            StudioOutputSection(title: "Who feels it", guidance: "The people affected, and how the need touches their daily work."),
            StudioOutputSection(title: "Evidence", guidance: "Volumes, timings, examples, and testimony that show the need is real."),
            StudioOutputSection(title: "Cost of inaction", guidance: "What happens if nothing changes.")
        ],
        howToWrite: [
            "Start with the people affected, and describe the need in their words before adding your own. Gather evidence that shows the size and shape of the need: how often it happens, how long it lasts, and what it costs. Write the cost of doing nothing as carefully as the need itself, because that cost is the reason to act. Read the statement back and remove any sentence that names a solution; if the answer is already in the statement, the statement is doing the solution's job."
        ],
        workedExampleTitle: "Worked example: need statement for payment status answers",
        workedExample: [
            "Problem: officers cannot answer customer queries about payment status without a manual check, and the checks are slow and sometimes inconsistent. Who feels it: operations officers, who lose time, and corporate customers, who wait for answers. Evidence: the query log shows the same question asked repeatedly, and a sample of cases shows answers taking far longer than the target. Cost of inaction: continued manual effort, inconsistent answers, and growing customer frustration.",
            "An early draft of the statement said the need was a new status screen. That draft was rewritten: a screen is a solution, and naming it would have closed off simpler options, such as a daily status file or a change to the query script. The rewritten statement described only the pain and its evidence, and the team then compared options on their merits."
        ],
        keyPoints: [
            "A need is a problem or an opportunity, stated without naming a solution.",
            "Support every need with evidence: volumes, timings, examples, and testimony.",
            "State the cost of doing nothing; it is the reason to act."
        ],
        practiceScenarios: [],
        practiceQuestions: [],
        linkedExerciseIDs: [],
        suggestedMinimumWords: 120,
        suggestedMaximumWords: 350
    ),
    StudioLesson(
        id: "lesson-concept-solution",
        title: "Solution",
        subtitle: "A solution is a specific way of satisfying one or more needs in a context.",
        kind: .concept,
        level: .foundation,
        knowledgeArea: nil,
        babokReference: "2.1",
        explanation: [
            "A solution is a specific way of satisfying one or more needs in a context. It is specific: not a wish, but a defined combination of process, people, rules, information, and technology that can be built, tested, and supported. One solution may serve several needs, and one need may be served by several possible solutions. The analyst's job is to describe solutions clearly enough to compare them, and to recommend the one that delivers the most value for the least cost and risk.",
            "Solutions are judged in context. A solution that works well in one organisation may fail in another with different systems, skills, or rules. Solutions also have a life: they are designed, built, used, maintained, and eventually replaced or retired. Describing a solution means describing its parts, how they fit together, what it changes for the people who use it, and what it needs to keep working. A solution described only as a system name is not described at all."
        ],
        outputName: "Solution description",
        outputStructure: [
            StudioOutputSection(title: "Needs served", guidance: "The needs this solution satisfies, each traced to the need statement."),
            StudioOutputSection(title: "How it works", guidance: "The parts of the solution, and how they fit together."),
            StudioOutputSection(title: "What changes", guidance: "What changes for the people who use it, and for the teams around it."),
            StudioOutputSection(title: "Support needs", guidance: "What the solution needs to keep working: data, skills, controls, and maintenance.")
        ],
        howToWrite: [
            "Start from the needs the solution serves, and trace each part of the solution back to a need it satisfies. Describe how the parts fit together in plain words, before any technical detail: a reader who cannot follow the plain description will not be helped by diagrams. State what changes for users honestly, including new effort and new learning, and list what the solution needs to keep working. A solution that needs support nobody can give is a future failure wearing a present success."
        ],
        workedExampleTitle: "Worked example: solution description for a payment status screen",
        workedExample: [
            "Needs served: faster, accurate status answers for customers, and less manual checking for officers. How it works: the status feed writes the latest status and its time to the screen officers already use, and the screen shows a plain message when no status has been received. What changes: officers read the screen instead of telephoning, and the back office receives fewer status calls. Support needs: the feed must be monitored, the status definitions must be owned by operations, and new officers must be trained on the no status message.",
            "Comparing this solution with an alternative, a daily status file, showed the trade off clearly. The file was cheaper but left answers a day old, so it served the need only partly. The live screen served the need fully at higher cost. The description recorded both options and the reasoning, and the sponsor chose the live screen with open eyes."
        ],
        keyPoints: [
            "A solution is a specific combination of process, people, rules, information, and technology.",
            "Trace every part of a solution back to a need it satisfies.",
            "Describe what changes for users and what the solution needs to keep working."
        ],
        practiceScenarios: [],
        practiceQuestions: [],
        linkedExerciseIDs: [],
        suggestedMinimumWords: 120,
        suggestedMaximumWords: 350
    ),
    StudioLesson(
        id: "lesson-concept-stakeholder",
        title: "Stakeholder",
        subtitle: "A stakeholder is a group or individual with a relationship to the change, the need, or the solution.",
        kind: .concept,
        level: .foundation,
        knowledgeArea: nil,
        babokReference: "2.1",
        explanation: [
            "A stakeholder is a group or individual with a relationship to the change, the need, or the solution. That relationship may be interest, impact, or influence: stakeholders care about the change, are affected by it, or can shape it. The same person can be a stakeholder in several ways at once. An operations manager may feel the pain of the need, be affected by the solution, and influence whether the change is approved.",
            "Stakeholders define value. A solution delivers value only when the people it serves judge that it does, so the analyst must learn what each stakeholder group wants, worries about, and will judge. Stakeholders also hold the knowledge analysis needs: how work really happens, what rules bind it, and what has been tried before. Missing a stakeholder group does not remove its needs. It delays the moment those needs appear, when they cost more to meet."
        ],
        outputName: "Stakeholder note",
        outputStructure: [
            StudioOutputSection(title: "Group", guidance: "The stakeholder group, named by its relationship to the change."),
            StudioOutputSection(title: "Relationship", guidance: "Interest, impact, or influence, and how the group is affected."),
            StudioOutputSection(title: "Wants and worries", guidance: "What the group wants from the change, and what it worries about."),
            StudioOutputSection(title: "What is needed", guidance: "The information, decisions, or approval needed from this group.")
        ],
        howToWrite: [
            "Name groups by their relationship to the change, not by job title alone, and record interest, impact, and influence separately: a group with high impact and low influence is easily overlooked and often the most affected. For each group, write what it wants and what it worries about in its own terms, then name what you need from it: information, a decision, or approval. Revisit the note as the change grows, because new groups appear and old groups change their minds."
        ],
        workedExampleTitle: "Worked example: stakeholder note for a payment status change",
        workedExample: [
            "Groups for the status screen change: operations officers (impact: daily work changes; interest: faster answers), the corporate banking team (interest: accurate answers for customers), compliance (influence: owns the wording rules for status messages), and the technology team (impact: builds and supports the feed). Officers want speed and accuracy, and worry the screen may overstate what is known. Compliance worries that a status may promise more than the evidence supports.",
            "The note showed that compliance, the group with the power to block the wording, had the least time available. The analyst booked the wording review two weeks ahead and kept the rest of the work moving without waiting for it. Naming the relationship early turned a late surprise into a planned step."
        ],
        keyPoints: [
            "Stakeholders relate to the change through interest, impact, or influence.",
            "Stakeholders define value, so their wants and worries must be learned, not assumed.",
            "Revisit the stakeholder picture as the change grows; new groups appear."
        ],
        practiceScenarios: [],
        practiceQuestions: [],
        linkedExerciseIDs: [],
        suggestedMinimumWords: 120,
        suggestedMaximumWords: 350
    ),
    StudioLesson(
        id: "lesson-concept-value",
        title: "Value",
        subtitle: "Value is the worth, importance, or usefulness of something to a stakeholder within a context.",
        kind: .concept,
        level: .foundation,
        knowledgeArea: nil,
        babokReference: "2.1",
        explanation: [
            "Value is the worth, importance, or usefulness of something to a stakeholder within a context. Value is always judged by someone, in some setting: the same change can be valuable to one group and costly to another, and valuable this year but not next. Value can be tangible, such as money saved or time recovered, or intangible, such as trust, reputation, or confidence. Both kinds are real, and both must be stated honestly.",
            "Because value is judged by stakeholders, the analyst must agree what value means before the change is built, and measure it after the change is live. A value statement written only after delivery is a story told to justify what happened. A value statement agreed in advance, with measures and a baseline, lets everyone judge the change fairly, including judging it a failure when the value did not arrive. That honesty is what makes the next decision better."
        ],
        outputName: "Value statement",
        outputStructure: [
            StudioOutputSection(title: "Value claimed", guidance: "What value the change will deliver, and to whom."),
            StudioOutputSection(title: "Measures", guidance: "How the value will be recognised, with a baseline measured before the change."),
            StudioOutputSection(title: "Trade offs", guidance: "What the change costs, and who bears the cost."),
            StudioOutputSection(title: "Judgement point", guidance: "When and how the value will be judged after the change is live.")
        ],
        howToWrite: [
            "Write the value from the stakeholder's point of view, in their words, and separate tangible value from intangible value rather than forcing every benefit into money. Agree the measures and take the baseline before the change goes live, or the judgement afterwards will rest on memory. State the trade offs plainly: who pays, who waits, and who loses something. End with a judgement point: a date and a method for deciding whether the value arrived."
        ],
        workedExampleTitle: "Worked example: value statement for a payment status change",
        workedExample: [
            "Value claimed: faster, accurate status answers for corporate customers, and less manual checking for officers. Measures: time from query to answer, and the number of status telephone calls per week, both baselined from the query log before the change. Trade offs: the technology team carries the build and the feed monitoring, and officers must learn the new no status message. Judgement point: four weeks after go live, the measures are compared with the baseline and reported to the sponsor.",
            "After four weeks, query time had fallen and telephone calls had dropped, but one payment type still needed manual checks. The value statement made the partial success visible: the change delivered value for the payment types it covered, and the remaining gap had a named owner. The sponsor judged the change fairly, because the measures had been agreed in advance."
        ],
        keyPoints: [
            "Value is judged by stakeholders, within a context; it is never absolute.",
            "Agree measures and a baseline before the change, and judge afterwards.",
            "State trade offs plainly: who pays, who waits, and who loses something."
        ],
        practiceScenarios: [],
        practiceQuestions: [],
        linkedExerciseIDs: [],
        suggestedMinimumWords: 120,
        suggestedMaximumWords: 350
    ),
    StudioLesson(
        id: "lesson-concept-context",
        title: "Context",
        subtitle: "Context is the circumstances that influence, are influenced by, and provide understanding of the change.",
        kind: .concept,
        level: .foundation,
        knowledgeArea: nil,
        babokReference: "2.1",
        explanation: [
            "Context is the circumstances that influence, are influenced by, and provide understanding of the change. It includes the rules that bind the work, the systems that carry it, the habits of the teams, the timing of the business cycle, and the wider market. Context shapes what is possible: a solution that fits the rules in one country may break them in another, and a change that suits a quiet period may be reckless during a peak.",
            "Context is easy to ignore because it feels like background, but it decides whether a change lands well. The analyst must make the relevant context visible: the constraints that cannot move, the assumptions that could move, and the neighbouring changes that interact with this one. Context also changes over time. A new rule, a new system, or a reorganisation can alter the setting a change was designed for, and the analysis must be revisited when that happens."
        ],
        outputName: "Context note",
        outputStructure: [
            StudioOutputSection(title: "Constraints", guidance: "The rules, limits, and fixed points the change must respect."),
            StudioOutputSection(title: "Systems and data", guidance: "The systems and data the change touches, and their limits."),
            StudioOutputSection(title: "People and habits", guidance: "How teams work today, and what they rely on."),
            StudioOutputSection(title: "Neighbouring changes", guidance: "Other changes that interact with this one, and how.")
        ],
        howToWrite: [
            "List the constraints first, and mark each as fixed or movable: a fixed constraint shapes the solution, while a movable one is a decision waiting to be made. Describe the systems and data honestly, including their limits, and describe how people actually work, not how the manual says they work. End with neighbouring changes and their interactions, and name the owner who will tell you when the context shifts. A context note with no owner goes stale silently."
        ],
        workedExampleTitle: "Worked example: context note for a payment status change",
        workedExample: [
            "Constraints: status wording must follow the compliance rules, and no status may overstate what is known. Systems and data: three systems supply status reports, and one payment type has no report. People and habits: officers telephone the back office when the screen is silent, and customers expect an answer within the working day. Neighbouring changes: a separate change is replacing the back office queue, which will alter the telephone route officers use as a fallback.",
            "The neighbouring change mattered more than expected. When the queue replacement slipped by a month, the fallback route stayed in place longer, and the status screen change had to be judged with the old fallback still running. Because the context note had recorded the interaction, the delay was understood as a context shift, not as a failure of the screen change."
        ],
        keyPoints: [
            "Context shapes what is possible; make it visible instead of treating it as background.",
            "Mark constraints as fixed or movable, and describe systems, data, and habits honestly.",
            "Record neighbouring changes and name an owner to report when context shifts."
        ],
        practiceScenarios: [],
        practiceQuestions: [],
        linkedExerciseIDs: [],
        suggestedMinimumWords: 120,
        suggestedMaximumWords: 350
    ),
    StudioLesson(
        id: "lesson-concept-business-analysis",
        title: "Business Analysis",
        subtitle: "Business analysis is the practice of enabling change by defining needs and recommending solutions that deliver value.",
        kind: .concept,
        level: .foundation,
        knowledgeArea: nil,
        babokReference: "2.2",
        explanation: [
            "Business analysis is the practice of enabling change in an enterprise by defining needs and recommending solutions that deliver value to stakeholders. The definition names the whole job in one sentence: understand the need, shape a solution, and make sure the solution is worth something to the people it serves. Analysis is the work between the problem and the answer. It turns a vague request into a clear, agreed, testable description of what should change and why.",
            "The analyst enables change; the analyst does not own it. Decisions belong to the stakeholders who carry the risk and the benefit, and the analyst's contribution is evidence, clarity, and honest options. That distinction matters in daily work. An analyst who decides for others takes on risk that is not theirs, and an analyst who only records what others say adds no judgement. Good analysis sits between the two: it challenges, tests, and clarifies, then hands the decision back with the reasoning attached."
        ],
        outputName: "Business analysis brief",
        outputStructure: [
            StudioOutputSection(title: "Change", guidance: "The change this analysis serves, in one sentence."),
            StudioOutputSection(title: "Need", guidance: "The need as understood so far, and what is still unclear."),
            StudioOutputSection(title: "Stakeholders", guidance: "The people affected, and the decisions they must make."),
            StudioOutputSection(title: "Analysis plan", guidance: "The analysis work planned, and the outputs it will produce.")
        ],
        howToWrite: [
            "Write the brief before the detailed work starts, and keep it to one page. State the change and the need as understood so far, marking clearly what is still unclear, and name the stakeholders and the decisions they must make. End with the analysis plan: the work you will do, the outputs you will produce, and when decisions are needed. Share the brief with the stakeholders and correct it from their feedback; a brief nobody has read is a private note, not an agreement."
        ],
        workedExampleTitle: "Worked example: business analysis brief for a payment status change",
        workedExample: [
            "Change: show live payment status on the operations screen. Need as understood: officers cannot answer status queries without manual checks; unclear: which payment types lack a status report. Stakeholders: operations, corporate banking, compliance, technology. Analysis plan: confirm the status feed coverage, agree the wording rules, and describe the screen change, with a decision on scope needed before build starts.",
            "The brief was shared with all four groups, and compliance corrected one point: the wording rules applied to customer facing messages, not only to the screen. That correction changed the analysis plan, because the wording review had to cover two surfaces. The brief, corrected early, saved a late surprise."
        ],
        keyPoints: [
            "Business analysis enables change by defining needs and recommending solutions that deliver value.",
            "The analyst provides evidence and options; decisions belong to stakeholders.",
            "Write the brief early, share it, and correct it from feedback."
        ],
        practiceScenarios: [],
        practiceQuestions: [],
        linkedExerciseIDs: [],
        suggestedMinimumWords: 120,
        suggestedMaximumWords: 350
    ),
    StudioLesson(
        id: "lesson-concept-business-analysis-information",
        title: "Business Analysis Information",
        subtitle: "Business analysis information is the broad set of information that analysts analyse, transform, and report.",
        kind: .concept,
        level: .foundation,
        knowledgeArea: nil,
        babokReference: "2.2",
        explanation: [
            "Business analysis information is the broad and diverse set of information that business analysts analyse, transform, and report. It covers far more than requirements: elicitation results, designs, solution options, solution scope, change strategy, decisions, and assumptions all count. Anything that is an input to, or an output of, analysis work is business analysis information, at any level of detail.",
            "The breadth matters because it widens the analyst's duty of care. If only requirements were managed, then decisions, assumptions, and options could drift without trace, and nobody could later explain why a choice was made. Treating all of it as information to be managed means every piece is named, owned, stored where others can find it, and kept current. When a stakeholder asks why a decision was made, the answer should be findable, not remembered."
        ],
        outputName: "Business analysis information list",
        outputStructure: [
            StudioOutputSection(title: "Item", guidance: "Each piece of information, named and described in one line."),
            StudioOutputSection(title: "Type", guidance: "What kind of information it is: requirement, design, decision, assumption, option, or other."),
            StudioOutputSection(title: "Owner", guidance: "The person who keeps the item current."),
            StudioOutputSection(title: "Location", guidance: "Where the item lives, so others can find it.")
        ],
        howToWrite: [
            "List every piece of information the analysis produces or relies on, not only the formal documents: workshop notes, decision records, and assumption lists count too. Give each item a name, a type, an owner, and a location, and review the list regularly, removing what is stale and adding what is new. An item with no owner or no location is an item that will be lost; the list exists to prevent exactly that."
        ],
        workedExampleTitle: "Worked example: information list for a payment status change",
        workedExample: [
            "Items for the status screen change: the need statement, the elicitation notes from two officer interviews, the status wording decisions, the solution description, the assumption that all payment types produce a status report, and the decision to narrow scope. Each item has an owner and a location in the shared workspace. The assumption is listed as information in its own right, so it is checked rather than forgotten.",
            "Three weeks later, a new team member asked why one payment type was excluded from scope. The answer was in the information list: the decision record, the assumption behind it, and the elicitation note that showed the missing report. The new member understood the history in minutes, without asking anyone to reconstruct it from memory."
        ],
        keyPoints: [
            "Business analysis information covers far more than requirements: decisions, assumptions, options, and designs count too.",
            "Every item needs a name, an owner, and a location where others can find it.",
            "Review the list regularly, removing what is stale and adding what is new."
        ],
        practiceScenarios: [],
        practiceQuestions: [],
        linkedExerciseIDs: [],
        suggestedMinimumWords: 120,
