            "Postman"
        ],
        certifications: [StudioCertification(name: "ECBA", body: "IIBA", note: "Suits beginners with little or no BA experience who want an entry-level credential early in the journey."), StudioCertification(name: "CCBA", body: "IIBA", note: "Suits analysts with some BA work experience who want an intermediate credential after building practical evidence."), StudioCertification(name: "CBAP", body: "IIBA", note: "Suits experienced analysts as a later goal, once years of BA work meet the eligibility requirements."), StudioCertification(name: "PMI-PBA", body: "PMI", note: "Suits analysts who work closely with projects and want a credential focused on business analysis within project delivery."), StudioCertification(name: "PSPO", body: "Scrum.org", note: "Suits analysts working in Scrum teams who want a related option focused on the product owner role and backlog ownership.")],
        portfolio: [
            "Business requirements document for a practice project",
            "Current and future process flows for one change",
            "Stakeholder map with engagement plan",
            "User stories with acceptance criteria",
            "Traceability list linking needs to test checks",
            "Workshop plan, notes, and agreed actions",
