        ],
        certifications: [StudioCertification(name: "PSPO", body: "Scrum.org", note: "Suits self directed learners who want to test their understanding through an assessment before or soon after starting Product Owner work."), StudioCertification(name: "CSPO", body: "Scrum Alliance", note: "Suits learners who prefer guided training with discussion, taken when starting out or preparing for a first Product Owner role."), StudioCertification(name: "CBAP", body: "IIBA", note: "Suits experienced business analysts on the BA to PO path who want a supporting credential that evidences analysis depth alongside Product Owner experience.")],
        portfolio: [
