        certifications: [StudioCertification(name: "PSPO", body: "Scrum.org", note: "Suits people moving into Product Owner or product work who want a recognised grounding in product ownership, best taken after some practical backlog or delivery experience."), StudioCertification(name: "CSPO", body: "Scrum Alliance", note: "Suits people new to Product Owner work who want structured learning in the role, best taken when starting or preparing for Product Owner responsibilities."), StudioCertification(name: "PMI-PBA", body: "PMI", note: "Suits business analysts and others with analysis experience who want a related business analysis credential alongside product work, best taken after building solid analysis experience.")],
        portfolio: [
