        certifications: [StudioCertification(name: "CCBA", body: "IIBA", note: "Suits analysts with some practical experience who want a recognised foundation before aiming for a more advanced credential."), StudioCertification(name: "CBAP", body: "IIBA", note: "Suits experienced analysts who want to evidence senior level practice, and certification supports but does not replace evidence of work."), StudioCertification(name: "PMI-PBA", body: "PMI", note: "Suits analysts who work closely with projects and programmes and want to evidence business analysis within project delivery."), StudioCertification(name: "PSPO", body: "Scrum.org", note: "Suits analysts moving toward product ownership who want to evidence skills in maximising value and managing a product backlog."), StudioCertification(name: "CSPO", body: "Scrum Alliance", note: "Suits analysts moving toward product ownership who prefer a course-based route to evidencing product owner skills.")],
        portfolio: [
